import random, heapq
random.seed(0)
# admissible: 0 <= h(n) <= h*(n). Test each option on random admissible pairs.
ops = {'A': lambda a, b: a + b, 'B': lambda a, b: a * b,
       'C': lambda a, b: a / b, 'D': lambda a, b: abs(a - b)}
viol = {k: None for k in ops}
for _ in range(100000):
    hs = random.uniform(0, 10)                              # true cost-to-goal h*(n)
    h1, h2 = random.uniform(0, hs), random.uniform(1e-9, hs)
    for k, f in ops.items():
        if f(h1, h2) > hs + 1e-12 and viol[k] is None:
            viol[k] = tuple(round(v, 3) for v in (hs, h1, h2, f(h1, h2)))
print(viol)                                                 # only D has no counterexample
assert viol['D'] is None and all(viol[k] for k in 'ABC')
# A* on a tiny graph: S->G costs 4.5 directly; S->A->G costs 1+2 = 3 (optimal). h*(A) = 2.
E = {'S': [('A', 1), ('G', 4.5)], 'A': [('G', 2)], 'G': []}
def astar(hA):                                              # h(S)=0, h(G)=0 (trivially admissible)
    h = {'S': 0, 'A': hA, 'G': 0}; pq = [(0, 0, 'S')]
    while pq:
        f, g, n = heapq.heappop(pq)
        if n == 'G': return g
        for m, c in E[n]: heapq.heappush(pq, (g + c + h[m], g + c, m))
for h1A, h2A in [(2, 2), (2, 0.5)]:                         # both admissible at A (<= 2)
    print((h1A, h2A), {k: (f(h1A, h2A), astar(f(h1A, h2A))) for k, f in ops.items()})
